const items = $input.all().filter(item => item.json.title);

const texts = items.map(item => {
  const title = item.json.title || '';
  const content = item.json.content || '';

  const sentences = content
    .split(/(?<=[.!?])\s+/)
    .filter(s => s.trim().length > 0)
    .slice(0, 3);

  const excerpt = sentences.join(' ');

  return `${title}. ${excerpt}`.trim();
});

return [{
  json: {
    texts,
    items: items.map(item => item.json)
  }
}];

const response = $input.first().json;
const embeddings = response.embeddings;

const originalItems = $('Prepare Embedding Input').first().json.items;

if (embeddings.length !== originalItems.length) {
  throw new Error(
    `Desajuste: ${embeddings.length} embeddings recibidos vs ${originalItems.length} artículos originales`
  );
}

return originalItems.map((item, index) => ({
  json: {
    ...item,
    embedding: embeddings[index]
  }
}));

