const items = $input.all();
const articles = items.map(item => item.json);

// Postgres devuelve embedding como JSONB -> puede llegar como string o como array ya parseado
const getEmbedding = (article) => {
  return typeof article.embedding === 'string'
    ? JSON.parse(article.embedding)
    : article.embedding;
};

function cosineSimilarity(vecA, vecB) {
  let dotProduct = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < vecA.length; i++) {
    dotProduct += vecA[i] * vecB[i];
    normA += vecA[i] * vecA[i];
    normB += vecB[i] * vecB[i];
  }
  return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
}

const SIMILARITY_THRESHOLD = 0.83;
const n = articles.length;
const embeddings = articles.map(getEmbedding);

// Union-Find (Disjoint Set Union)
const parent = Array.from({ length: n }, (_, i) => i);

function find(i) {
  if (parent[i] !== i) {
    parent[i] = find(parent[i]);
  }
  return parent[i];
}

function union(i, j) {
  const rootI = find(i);
  const rootJ = find(j);
  if (rootI !== rootJ) {
    parent[rootJ] = rootI;
  }
}

// Comparar todos los pares (i, j) una sola vez
for (let i = 0; i < n; i++) {
  for (let j = i + 1; j < n; j++) {
    const similarity = cosineSimilarity(embeddings[i], embeddings[j]);
    if (similarity >= SIMILARITY_THRESHOLD) {
      union(i, j);
    }
  }
}

// Agrupar artículos por su raíz de cluster
const clustersMap = {};
for (let i = 0; i < n; i++) {
  const root = find(i);
  if (!clustersMap[root]) {
    clustersMap[root] = [];
  }
  clustersMap[root].push(articles[i]);
}

// Convertir a array de clusters, con metadatos útiles
const clusters = Object.values(clustersMap).map((articleGroup, index) => ({
  cluster_id: index,
  article_count: articleGroup.length,
  source_count: new Set(articleGroup.map(a => a.source_name)).size,
  sources: [...new Set(articleGroup.map(a => a.source_name))],
  articles: articleGroup.map(a => ({
    title: a.title,
    link: a.link,
    source_name: a.source_name,
    category: a.category
  }))
}));

return clusters.map(cluster => ({ json: cluster }));
